export type SyncResult = {
    repository: {
        uuid: string;
    };
    summary: {
        created: number;
        updated: number;
        unchanged: number;
        deleted: number;
    };
};

/**
 * Type of access token stored for this repository. ACCESS_TOKEN: a repository/workspace-scoped access token (Bitbucket Repository/Workspace Access Token, or a GitHub Personal Access Token). Git username: x-token-auth for Bitbucket, x-access-token for GitHub. ACCOUNT_API_TOKEN: Bitbucket-only Atlassian Account API Token (git username x-bitbucket-api-token-auth, REST username = account email). Not supported for GitHub.
 */
export type RepositoryTokenType = 'ACCESS_TOKEN' | 'ACCOUNT_API_TOKEN';

/**
 * Metadata about the stored access token (value is never returned)
 */
export type RepositoryTokenInfo = {
    type: RepositoryTokenType;
    /**
     * Account email for ACCOUNT_API_TOKEN (Bitbucket only, used as REST Basic-auth username); always null for ACCESS_TOKEN and for GitHub repositories.
     */
    email?: string;
    /**
     * When the token was last set or replaced
     */
    updated_at: string;
};

/**
 * Access token to store for this repository (write-only; the value is never returned by the API). GitHub repositories only support type=ACCESS_TOKEN (a GitHub Personal Access Token). Required for ACCOUNT_API_TOKEN (Bitbucket only): the email field must be the Atlassian account email.
 */
export type RepositoryAccessTokenInput = {
    /**
     * The raw token value (stored encrypted)
     */
    value: string;
    type: RepositoryTokenType;
    /**
     * Atlassian account email — required when type is ACCOUNT_API_TOKEN (Bitbucket only)
     */
    email?: string;
};

/**
 * Payload for creating a new repository. The identity (source, workspace, slug) is derived from clone_url; only the clone URL is required.
 */
export type RepositoryCreate = {
    /**
     * Git clone URL (HTTPS or SSH). source, workspace and slug are derived from it (bitbucket.org → BITBUCKET, github.com → GITHUB, otherwise LOCAL).
     */
    clone_url: string;
    /**
     * Optional human-readable display name; defaults to the derived slug.
     */
    display_name?: string;
    /**
     * Optional description
     */
    description?: string;
    /**
     * Optional access token. Only relevant for BITBUCKET and GITHUB repositories (ignored for LOCAL). Validated against the provider's API before being stored.
     */
    access_token?: RepositoryAccessTokenInput;
    /**
     * Per-repository doc-run model ref. Must be a valid bedrock model id from the doc-run-models list. Null = global env default.
     */
    doc_run_model_ref?: string;
    /**
     * Per-repository doc-run iteration limit (1–100). Null = global env default.
     */
    doc_run_max_iterations?: number;
};

/**
 * Payload for updating a repository (all fields optional)
 */
export type RepositoryPatch = {
    /**
     * Human-readable display name
     */
    display_name?: string;
    /**
     * Optional description
     */
    description?: string;
    /**
     * Replace the stored access token. The new token is validated against the repository's provider (Bitbucket or GitHub) before being stored. The previous token value is discarded immediately.
     */
    access_token?: RepositoryAccessTokenInput;
    /**
     * Per-repository doc-run model ref. Must be a valid bedrock model id from the doc-run-models list. Null = global env default.
     */
    doc_run_model_ref?: string;
    /**
     * Per-repository doc-run iteration limit (1–100). Null = global env default.
     */
    doc_run_max_iterations?: number;
};

/**
 * A single model available for per-repository doc-runs
 */
export type DocRunModelEntry = {
    /**
     * Full model ref in "provider::model" format
     */
    id: string;
    /**
     * Human-readable model name
     */
    display_name: string;
    /**
     * Short description of the model
     */
    description: string;
    /**
     * Whether this model is the recommended default
     */
    recommended: boolean;
};

/**
 * Available doc-run models and the current global default
 */
export type DocRunModelList = {
    models: Array<DocRunModelEntry>;
    /**
     * The effective global default model ref (from PROCESS_DOCS_MODEL env var or built-in fallback)
     */
    default_model_ref: string;
};

