/**
 * Lightweight artifact list item with primary chat routing hint
 */
export type ArtifactListItem = {
    /**
     * Artifact UUID
     */
    id: string;
    /**
     * Artifact title
     */
    title: string;
    /**
     * Latest version number
     */
    latest_version: number;
    /**
     * ISO 8601 creation timestamp
     */
    created_at: string;
    /**
     * ISO 8601 last update timestamp
     */
    updated_at: string;
    /**
     * UUID of the most recently updated chat that references this artifact (null if no refs exist)
     */
    source_chat_id: string;
    /**
     * Chatbot code of the source chat (null if no refs exist)
     */
    source_chatbot_code: string;
    /**
     * Whether the current user is the direct owner of this artifact
     */
    is_owner: boolean;
    /**
     * Effective permission of the requesting user (READ < EDIT < MANAGE)
     */
    permission: 'READ' | 'EDIT' | 'MANAGE';
    /**
     * True when this artifact is shared with the current user via task cascade (not directly owned)
     */
    shared: boolean;
    kind: ArtifactKind;
    /**
     * Review state of the latest version (null if version data not available)
     */
    review_state?: 'UNCHECKED' | 'IN_REVIEW' | 'APPROVED' | 'NEEDS_REVISION' | 'SUPERSEDED';
    /**
     * Number of APPROVED decisions (only non-null for IN_REVIEW artifacts)
     */
    review_approved_count?: number;
    /**
     * Number of REJECTED decisions (only non-null for IN_REVIEW artifacts)
     */
    review_rejected_count?: number;
    /**
     * Total number of required reviewers (only non-null for IN_REVIEW artifacts)
     */
    review_total_required?: number;
    /**
     * True when this artifact has an open review assignment for the requesting user with no decision yet
     */
    pending_for_me: boolean;
};

/**
 * Paginated list of artifacts
 */
export type ArtifactList = {
    /**
     * Artifact items for the current page
     */
    items: Array<ArtifactListItem>;
    pagination: Pagination;
};

export type AcceptArtifactMemoryResponse = {
    /**
     * True when watermark matched and no new ingest job was enqueued
     */
    skipped: boolean;
    /**
     * KG_INGEST_ITEM ScriptRun UUID when enqueued
     */
    run_id: string;
    /**
     * SHA-256 hash of the accepted artifact body
     */
    content_hash: string;
    /**
     * Human-readable status when skipped
     */
    message?: string;
};

/**
 * Full artifact detail including the body of the requested version
 */
export type ArtifactDetail = {
    /**
     * Artifact UUID
     */
    id: string;
    /**
     * Artifact title
     */
    title: string;
    /**
     * Latest version number (for future version switcher)
     */
    latest_version: number;
    /**
     * Version currently loaded (equals latest_version in T01)
     */
    version: number;
    /**
     * Markdown body of the loaded version
     */
    body: string;
    /**
     * Optional short summary
     */
    summary: string;
    /**
     * Parsed OKF frontmatter (key/value metadata) of the loaded version; null when the version has none
     */
    frontmatter: {
        [key: string]: unknown;
    };
    /**
     * Raw YAML rendering of the frontmatter (without --- fences); null when the version has none
     */
    frontmatter_raw: string;
    /**
     * ISO 8601 creation timestamp
     */
    created_at: string;
    /**
     * ISO 8601 last update timestamp
     */
    updated_at: string;
    /**
     * UUID of the most recently updated chat that references this artifact (null if no refs exist)
     */
    source_chat_id: string;
    /**
     * Title of the source chat (raw chat.title, may be null; frontend renders 'Unbenannter Chat' as fallback)
     */
    source_chat_title: string;
    /**
     * Chatbot code of the source chat (null if no refs exist)
     */
    source_chatbot_code: string;
    /**
     * True if the requesting user is the direct owner of this artifact (MANAGE level)
     */
    is_owner: boolean;
    /**
     * Effective permission of the requesting user (READ < EDIT < MANAGE)
     */
    permission: 'READ' | 'EDIT' | 'MANAGE';
    /**
     * Review state of the loaded version (null if version data not available)
     */
    review_state: 'UNCHECKED' | 'IN_REVIEW' | 'APPROVED' | 'NEEDS_REVISION' | 'SUPERSEDED';
    kind: ArtifactKind;
    /**
     * Display name of the artifact owner (who created the artifact); null when not available
     */
    created_by_name: string;
    /**
     * Display name of the user who authored the currently loaded version; null for legacy versions or when same as created_by_name
     */
    version_author_name: string;
    /**
     * UUID of the artifact this review document was written for; non-null only when kind is REVIEW
     */
    review_of_artifact_id: string;
    /**
     * Version of the reviewed artifact this review document was written for; non-null only when kind is REVIEW
     */
    review_of_version: number;
    /**
     * Title of the reviewed artifact; non-null only when kind is REVIEW and the parent artifact still exists
     */
    review_of_artifact_title: string;
};

/**
 * Lightweight artifact summary used in the chat artifact switcher
 */
export type ChatArtifactSummary = {
    /**
     * Artifact UUID
     */
    id: string;
    /**
     * Artifact title
     */
    title: string;
    /**
     * Latest version number
     */
    latest_version: number;
    /**
     * ISO 8601 last update timestamp
     */
    updated_at: string;
    /**
     * Review state of the latest version (null if version data not available)
     */
    review_state: 'UNCHECKED' | 'IN_REVIEW' | 'APPROVED' | 'NEEDS_REVISION' | 'SUPERSEDED';
    kind: ArtifactKind;
};

/**
 * Non-paginated list of artifacts linked to a chat (switcher index)
 */
export type ChatArtifactList = {
    /**
     * Artifacts linked to the chat, sorted by updatedAt DESC
     */
    items: Array<ChatArtifactSummary>;
};

/**
 * Lightweight task reference attached to an artifact
 */
export type ArtifactTaskRef = {
    /**
     * Task UUID
     */
    id: string;
    /**
     * Human-readable, immutable task identifier (e.g. "AURA-42") — used for browser links; id stays the API identifier (ANW-7848).
     */
    human_key: string;
    /**
     * Task title
     */
    title: string;
    /**
     * Task status
     */
    status: 'OPEN' | 'ARCHIVED';
};

/**
 * Non-paginated list of tasks linked to an artifact
 */
export type ArtifactTaskList = {
    /**
     * Tasks linked to the artifact, sorted by updatedAt DESC
     */
    items: Array<ArtifactTaskRef>;
};

/**
 * One person with access to a shared entity (task or artifact), for the flat share-modal list (ANW-7754). Roles are TaskRoles when access comes from task membership; empty for a standalone artifact owner.
 *
 */
export type ShareAccessPerson = {
    user: UserPickerItem;
    /**
     * Union of TaskRoles across linked tasks (deduplicated).
     */
    roles: Array<TaskRole>;
};

/**
 * One entry in an artifact's own access list (ArtifactAccessGrant, S1 · AURA-921), the source the reviewer-access grant endpoints manage (S3, AURA-923). Only USER-principal grants resolve to a single person; COMPANY-principal grants have none and are omitted from this list (they still count toward broad_access).
 *
 */
export type ArtifactGrantEntry = {
    user: UserPickerItem;
    /**
     * Level granted to this principal via the artifact's own access list. Mirrors the ArtifactGrantLevel enum: MANAGE stays reserved for ownership and can never appear in a grant row.
     *
     */
    level: 'READ' | 'EDIT';
};

/**
 * Flat, read-only access list for an artifact (ANW-7754). Always includes the artifact owner; when linked to one or more tasks, also includes direct TaskMembers of those tasks (deduplicated, roles unioned).
 *
 */
export type ArtifactAccessOverview = {
    /**
     * True when the artifact is linked to at least one task.
     */
    linked_to_task: boolean;
    /**
     * Deduplicated people with access, sorted by display name.
     */
    items: Array<ShareAccessPerson>;
    /**
     * Sources of broad (non-individual) access via linked tasks — direct or inherited whole-company/group grants, open owner-/crew-search (ANW-7907, S4). Empty when nothing broad applies or the artifact is standalone. Powers the warning box in ShareModal; USER grants are excluded. Every level is READ regardless of the source task's grant.
     *
     */
    broad_access: Array<BroadAccessEntry>;
    /**
     * Direct entries in the artifact's own access list (S3, AURA-923), managed via POST/DELETE /artifacts/{id}/grants.
     *
     */
    grants: Array<ArtifactGrantEntry>;
    /**
     * True when the viewer may add/remove entries in `grants` (resolved permission MANAGE or higher) — what S5's share-dialog controls hang off.
     *
     */
    can_manage: boolean;
};

/**
 * A single version entry without body, used in the version history list
 */
export type ArtifactVersionListItem = {
    /**
     * Version number
     */
    version: number;
    /**
     * Optional short change note for this version
     */
    summary: string;
    /**
     * ISO 8601 creation timestamp
     */
    created_at: string;
    /**
     * UUID of the assistant message that created this version (null for user edits)
     */
    created_by_message_id: string;
    /**
     * Display name of the user who authored this version; null for legacy versions
     */
    created_by_name: string;
};

/**
 * Non-paginated version history for an artifact, sorted by version DESC
 */
export type ArtifactVersionList = {
    /**
     * Version list items sorted by version DESC
     */
    items: Array<ArtifactVersionListItem>;
};

/**
 * Derived archive state of a task (OPEN when archived_at is null, ARCHIVED otherwise); used only by the task graph node presentation.
 */
export type TaskArchiveState = 'OPEN' | 'ARCHIVED';

/**
 * Fixed workflow status of a task (ANW-7228; extended to the full T18 vocabulary in ANW-7459/S01). Orthogonal to archived_at and looking_for_owner_at. Which subset is valid for a given task depends on its level — see status_type and TaskLevel.
 */
export type TaskStatus = 'OPEN' | 'READY_FOR_REFINEMENT' | 'IN_REFINEMENT' | 'READY_FOR_ALIGNMENT' | 'IN_ALIGNMENT' | 'READY_FOR_DEVELOPMENT' | 'IN_DEVELOPMENT' | 'READY_FOR_REVIEW' | 'IN_REVIEW' | 'READY_FOR_DEPLOYMENT' | 'IN_DEPLOYMENT' | 'DONE' | 'DISCARDED';

/**
 * Derived machine-readable classification of a task's status (ANW-7459/S01) — OPEN (intake), WAITING (paused, "Ready for …"), ACTIVE (in progress, "In …"), TERMINAL (DONE/DISCARDED). Lets UI and logic tell "waiting" from "actively in progress" generically, without hard-coding every status. Not persisted; derived from status.
 */
export type TaskStatusType = 'OPEN' | 'WAITING' | 'ACTIVE' | 'TERMINAL';

/**
 * Hierarchy level of a task (Saga > Epic > Story > Sub-Task)
 */
export type TaskLevel = 'SAGA' | 'EPIC' | 'STORY' | 'SUBTASK';

/**
 * Workflow variant (T18 · S02, ANW-7522). DISCOVERY is the shortened concept workflow (Open → … → In Alignment → Done, no Development/Review/Deployment); selectable only for EPIC/STORY at creation and immutable afterwards.
 */
export type WorkflowVariant = 'STANDARD' | 'DISCOVERY';

/**
 * Classifies what kind of work the task represents. IDEA is a raw parked idea without a draft; DISCOVERY is deliberate exploratory work (spike, research, open architecture question).
 */
export type TaskType = 'FEATURE' | 'BUG' | 'IDEA' | 'CHORE' | 'DISCOVERY';

/**
 * Typed, directed relation between two tasks
 */
export type TaskRelationType = 'RELATES_TO' | 'PART_OF' | 'BLOCKS' | 'DUPLICATES';

/**
 * Sortable fields for task list
 */
export type TaskSortField = 'created_at' | 'updated_at' | 'title';

/**
 * Payload for creating a new task
 */
export type TaskCreate = {
    /**
     * Task title (required, 1–200 characters)
     */
    title: string;
    /**
     * Optional task description (Markdown)
     */
    description?: string;
    /**
     * UUID of the parent task. When set, the child level is derived automatically (one step below the parent in the fixed hierarchy SAGA→EPIC→STORY→SUBTASK).
     */
    parent_task_id?: string;
    /**
     * Hierarchy level for the task. Ignored when parent_task_id is set (level is then derived from parent). SUBTASK requires a parent.
     */
    level?: TaskLevel;
    /**
     * Work type of the task. Defaults to FEATURE if not specified.
     */
    type?: TaskType;
    /**
     * Workflow variant. Only EPIC/STORY may set DISCOVERY (400 otherwise); defaults to STANDARD, immutable after creation.
     */
    workflow_variant?: WorkflowVariant;
    /**
     * What the task covers — which components, pages or systems are in scope.
     */
    scope?: string;
    /**
     * Up to three tags to attach to the new task.
     */
    tags?: Array<{
        name: string;
        kind?: TagKind;
    }>;
    /**
     * Repositories to link to the new task.
     */
    repository_uuids?: Array<string>;
    /**
     * Chat this task originated from.
     */
    origin_chat_uuid?: string;
};

/**
 * Lightweight task list item
 */
export type TaskListItem = {
    /**
     * Task UUID (public identifier)
     */
    id: string;
    /**
     * Human-readable, immutable task identifier (e.g. "AURA-42"), assigned atomically on creation (ANW-7570).
     */
    human_key: string;
    /**
     * Task title
     */
    title: string;
    /**
     * Task description (Markdown, may be empty string)
     */
    description: string;
    /**
     * Task scope (what the task covers, may be empty string)
     */
    scope: string;
    status: TaskStatus;
    status_type: TaskStatusType;
    type: TaskType;
    /**
     * Hierarchy level (null if not assigned)
     */
    level?: TaskLevel;
    /**
     * UUID of the parent task (null if no parent)
     */
    parent_task_id?: string;
    /**
     * Slim parent task reference (null if no parent). Preferred over parent_task_id when title/level are needed (ANW-7743).
     */
    parent?: TaskHierarchyRef;
    /**
     * Number of direct child tasks
     */
    child_count?: number;
    /**
     * Number of direct child tasks with status OPEN
     */
    open_child_count?: number;
    /**
     * Number of direct child tasks with status ARCHIVED
     */
    archived_child_count?: number;
    /**
     * Number of non-archived direct children whose status is neither DONE nor DISCARDED (ANW-7743 board progress).
     */
    non_done_child_count?: number;
    /**
     * Direct TaskMember roles of the current user on this task. null = not a direct member; empty array = member without roles (ANW-7743).
     */
    my_roles?: Array<TaskRole>;
    /**
     * All OWNER members of this task (ANW-7743 story cards). Empty when the task has no owner.
     */
    owners?: Array<UserPickerItem>;
    /**
     * Number of chats linked to this task
     */
    chat_count: number;
    /**
     * Number of artifacts linked to this task
     */
    artifact_count: number;
    /**
     * Tags attached to this task
     */
    tags: Array<TaskTagRef>;
    /**
     * ISO 8601 timestamp when the task was archived (null if OPEN)
     */
    archived_at?: string;
    /**
     * ISO 8601 timestamp when owner search was started (null when not searching). Phase-preserving flag orthogonal to status (T18 · S10, ANW-7748).
     *
     */
    looking_for_owner_at?: string;
    /**
     * Durable one-sentence owner mandate (set on search start; kept after assignment).
     */
    owner_goal?: string;
    /**
     * Delivery due date for the owner goal (inherited by the assigned owner).
     */
    owner_goal_due_date?: string;
    /**
     * ISO 8601 timestamp when crew search was started (null when not searching). Phase-preserving flag orthogonal to status (T18 · S11, ANW-7759).
     *
     */
    looking_for_crew_at?: string;
    /**
     * Durable free-text crew need shown in the crew-search marketplace.
     */
    crew_need?: string;
    /**
     * Optional time horizon for the current crew need.
     */
    crew_need_due_date?: string;
    /**
     * True when the current user has not yet opened this task since the last notable change (readAt is null for this membership).
     */
    unread: boolean;
    /**
     * True when at least one comment by another user is newer than the viewer's comment-read watermark (AURA-999 / AURA-1082). Own comments never set this. Orthogonal to `unread` (task open-state).
     *
     */
    has_unread_comments: boolean;
    /**
     * Number of open (PENDING) owner applications — only populated by the owner-search pool list (GET /tasks/looking-for-owner, S10, ANW-7748); omitted on the general task list.
     *
     */
    owner_application_count?: number;
    /**
     * Number of open (PENDING) crew requests — only populated by the crew-search pool list (GET /tasks/looking-for-crew, S11, ANW-7759); omitted on the general task list.
     *
     */
    crew_request_count?: number;
    /**
     * Strict position within rank_context (1…n). Null while the task sits in the unprioritized tail (AURA-930 / AURA-1135).
     *
     */
    rank?: number;
    /**
     * Priority-order context key: "task:<parentTaskId>", "root:sagas", or "root:unparented" (AURA-930 / AURA-1135).
     *
     */
    rank_context: string;
    /**
     * ASAP class flag — shown above all ordered work when true; the task keeps its rank in its context (AURA-930).
     *
     */
    asap: boolean;
    /**
     * Optional visible justification for the current ranking (AURA-930).
     */
    rank_reason?: string;
    /**
     * ISO 8601 timestamp since when the task has been in its current status (T18 · S32). Distinct from updated_at, which changes on any field edit.
     */
    status_changed_at: string;
    /**
     * ISO 8601 creation timestamp
     */
    created_at: string;
    /**
     * ISO 8601 last update timestamp
     */
    updated_at: string;
};

/**
 * Paginated list of tasks
 */
export type TaskList = {
    /**
     * Task items for the current page
     */
    items: Array<TaskListItem>;
    pagination: Pagination;
};

/**
 * A node in the task graph — either a task or a tag.
 */
export type TaskGraphNode = {
    /**
     * Stable node id, namespaced by type (e.g. "task:<uuid>" or "tag:<slug>")
     */
    id: string;
    /**
     * Node category
     */
    type: 'task' | 'tag';
    /**
     * Underlying reference: task UUID for task nodes, tag slug for tag nodes
     */
    ref: string;
    /**
     * Human-readable, immutable task identifier (e.g. "AURA-42"), used as the click/navigation reference instead of `ref`. Absent/null on tag nodes; the internal node `id` (`task:<uuid>`) stays unaffected.
     */
    human_key?: string;
    /**
     * Display label (task title or tag name)
     */
    label: string;
    /**
     * Server-computed Louvain community index for cluster colouring
     */
    community: number;
    status?: TaskArchiveState;
    task_type?: TaskType;
    kind?: TagKind;
    /**
     * Hierarchy level of the task node (null for unleveled tasks; absent on tag nodes)
     */
    level?: TaskLevel;
    /**
     * Workflow status of the task node (absent on tag nodes); used for tooltip display, orthogonal to the archive `status` field above.
     */
    task_status?: TaskStatus;
};

/**
 * An edge in the task graph — a task-tag attachment or a typed task-task relation.
 */
export type TaskGraphEdge = {
    /**
     * Stable edge id
     */
    id: string;
    /**
     * Source node id
     */
    source: string;
    /**
     * Target node id
     */
    target: string;
    /**
     * Edge category
     */
    relation: 'TASK_TAG' | 'TASK_TASK';
    type?: TaskRelationType;
    /**
     * Whether the edge has a meaningful direction (true for PART_OF/BLOCKS)
     */
    directed: boolean;
};

/**
 * Renderer-agnostic task graph payload
 */
export type TaskGraph = {
    nodes: Array<TaskGraphNode>;
    edges: Array<TaskGraphEdge>;
};

/**
 * Slim card-shaped node for the hierarchy neighbourhood mini-map (ANW-7853). Carries the fields the shared task card renders, plus parent_task_id for layout and archived_at for MCP/agent consumers. Deliberately omits board-only fields such as subtree_size.
 */
export type TaskNeighborhoodNode = {
    /**
     * Task UUID (public identifier)
     */
    id: string;
    /**
     * Human-readable, immutable task identifier (e.g. "AURA-42")
     */
    human_key: string;
    /**
     * Task title
     */
    title: string;
    status: TaskStatus;
    /**
     * Hierarchy level (null for unleveled tasks)
     */
    level?: TaskLevel | null;
    /**
     * UUID of the parent task when that parent is also in this neighbourhood response; null for the root of the returned tree.
     */
    parent_task_id?: string;
    /**
     * Direct TaskMember roles of the caller. null = not a direct member; empty array = member without roles.
     */
    my_roles?: Array<TaskRole>;
    /**
     * All OWNER members of this task. Empty when the task has no owner.
     */
    owners: Array<UserPickerItem>;
    /**
     * ISO 8601 timestamp when owner search was started (null when not searching).
     */
    looking_for_owner_at?: string;
    /**
     * ISO 8601 timestamp when the task was archived, or null when active. Kept for agent consumers of getTaskNeighborhood (replaces the former OPEN/ARCHIVED graph status).
     */
    archived_at?: string;
};

/**
 * Hierarchy neighbourhood payload for the detail-view mini-map (ANW-7853).
 */
export type TaskNeighborhoodGraph = {
    nodes: Array<TaskNeighborhoodNode>;
    edges: Array<TaskBoardHierarchyEdge>;
};

/**
 * Whether the start bound of a stay was observed (AURA-1652).
 */
export type StayStartState = 'known' | 'unknown';

/**
 * End bound of a stay (AURA-1652). `running` means the task is still in this stay; `unknown` means the stay was left without an end event — never a duration of zero and never still running.
 */
export type StayEndState = 'known' | 'running' | 'unknown';

/**
 * One PHASE stay on a task (AURA-1654). Duration is computed at read time from the stored bounds.
 */
export type TaskStay = {
    id: string;
    kind: 'PHASE';
    status: TaskStatus;
    started_at: string;
    ended_at: string;
    start_state: StayStartState;
    end_state: StayEndState;
    /**
     * 1-based visit counter for this status on the task.
     */
    visit_index: number;
    /**
     * Total visits of this status on the task (so the UI can say "2. von 2").
     */
    visit_count: number;
    /**
     * Milliseconds between the bounds; null when a bound is missing so no duration can be computed.
     */
    duration_ms: number;
    /**
     * Status-change reason from ActivityEvent.payload.reason, if any.
     */
    reason: string;
};

/**
 * One owner-search or crew-search stay running alongside the phase strand (AURA-1654).
 */
export type TaskSearchStay = {
    id: string;
    kind: 'OWNER_SEARCH' | 'CREW_SEARCH';
    started_at: string;
    ended_at: string;
    start_state: StayStartState;
    end_state: StayEndState;
    visit_index: number;
    duration_ms: number;
};

/**
 * Cycle-time payload for one task (AURA-1654).
 */
export type TaskCycleTimes = {
    stays: Array<TaskStay>;
    searches: Array<TaskSearchStay>;
    /**
     * The running PHASE stay, or null when none is running.
     */
    current_stay: TaskStay | null;
    /**
     * True when the first PHASE stay starts with an unknown bound (history predates the activity log).
     */
    incomplete: boolean;
};

/**
 * One card in the ordering dialog (AURA-930 / AURA-1145). A restricted entry keeps its id and rank so the order stays complete and countable, but says nothing else about itself (d-022).
 */
export type TaskRankContextEntry = {
    /**
     * Task UUID (public identifier)
     */
    id: string;
    /**
     * Human-readable task identifier; null when restricted.
     */
    human_key: string;
    /**
     * Task title; null when restricted.
     */
    title: string;
    /**
     * Hierarchy level; null when unleveled or restricted.
     */
    level: TaskLevel | null;
    /**
     * Workflow status; null when restricted.
     */
    status: TaskStatus | null;
    /**
     * Position in the ordered zone; null = unordered.
     */
    rank: number;
    /**
     * ASAP class flag (AURA-930).
     */
    asap: boolean;
    /**
     * Optional rationale for the entry's placement (AURA-1147, d-004); null when restricted.
     */
    rank_reason: string;
    /**
     * Whether the caller owns this specific task — ASAP is owner-only (AURA-1147, d-017).
     */
    viewer_is_owner: boolean;
    /**
     * True when the caller may not read this task.
     */
    restricted: boolean;
    /**
     * The task's active core-team members (owner, contributor) — the card footer's entry into that person's full queue (AURA-930 / AURA-1148). Empty when restricted, same rule as every other field.
     */
    assignees: Array<PriorityAssigneeRef>;
    /**
     * The date-rail badge's governing deadline (AURA-930 / AURA-1149): the current phase's TaskPhaseGoal.deadline, else the next future phase deadline, else null (no badge). Null when restricted.
     */
    governing_date: string;
};

/**
 * A card assignee, with their committed capacity on this task if any (AURA-1146 Nachtrag: capacity on the ordering-dialog card).
 */
export type PriorityAssigneeRef = {
    id: string;
    display_name: string;
    /**
     * The assignee's committed capacity on this task; null when unset or not a core-team role.
     */
    capacity_percent: number;
};

/**
 * A priority-ordering context as the ordering dialog reads it (AURA-930 / AURA-1145 / AURA-1150).
 */
export type TaskRankContext = {
    /**
     * Context key — "task:<parentTaskId>", "root:sagas" or "root:unparented".
     */
    rank_context: string;
    /**
     * Fingerprint of the context's current ordering state. A save must carry this value back; a mismatch means the context moved on and the save is rejected.
     */
    expected_state: string;
    /**
     * Whether the caller has edit permission on the context and, if it is locked, is also its owner (d-019, AURA-1150).
     */
    viewer_can_reorder: boolean;
    /**
     * Whether the context's owner has locked it against non-owner reordering (AURA-1150).
     */
    locked: boolean;
    /**
     * Whether the caller is the context's owner and may (un)lock it (AURA-1150).
     */
    viewer_can_lock: boolean;
    /**
     * Ordered zone first (rank ascending), unordered set behind it.
     */
    entries: Array<TaskRankContextEntry>;
};

export type TaskRankContextOrder = {
    /**
     * Task UUIDs of the ordered zone, in target order. Every other living task in the context becomes unordered.
     */
    ordered_task_ids: Array<string>;
    /**
     * The `expected_state` this order was computed against.
     */
    expected_state: string;
};

/**
 * Result of setting or clearing ASAP (AURA-930 / AURA-1147, d-017).
 */
export type TaskAsapState = {
    /**
     * The task's ASAP flag after the call.
     */
    asap: boolean;
    /**
     * The task's current rationale, unchanged by this call.
     */
    rank_reason?: string;
    /**
     * Current ASAP stock across all living tasks (d-017).
     */
    asap_count: number;
};

export type TaskRankReasonInput = {
    /**
     * The rationale to publish; null clears it.
     */
    reason: string;
};

export type TaskRankReasonState = {
    /**
     * The task's rationale after the call.
     */
    rank_reason: string;
};

export type TaskRankReasonDraft = {
    /**
     * LLM-generated rationale draft — never persisted; the owner edits and publishes it.
     */
    draft: string;
};

/**
 * A single task card on the board. Slim by design — only the fields the board card renders, so a payload covering the caller's whole access scope stays small.
 */
export type TaskBoardNode = {
    /**
     * Task UUID (public identifier)
     */
    id: string;
    /**
     * Human-readable, immutable task identifier (e.g. "AURA-42")
     */
    human_key: string;
    /**
     * Task title
     */
    title: string;
    status: TaskStatus;
    status_type: TaskStatusType;
    type: TaskType;
    /**
     * Hierarchy level (null for unleveled tasks, which the board places outside the tree)
     */
    level?: TaskLevel;
    /**
     * UUID of the parent task, or null when the task has no parent or the parent lies outside the caller's access scope. In the latter case no hierarchy edge is emitted either — the board never draws ghost nodes.
     */
    parent_task_id?: string;
    /**
     * Direct TaskMember roles of the caller. null = not a direct member; empty array = member without roles.
     */
    my_roles?: Array<TaskRole>;
    /**
     * All OWNER members of this task. Empty when the task has no owner.
     */
    owners: Array<UserPickerItem>;
    /**
     * ISO 8601 timestamp when owner search was started (null when not searching).
     */
    looking_for_owner_at?: string;
    /**
     * Total number of descendants (children, grandchildren, …) of this task inside the board payload. Computed once per request via a recursive CTE — not the same as direct child count. Leaf tasks have subtree_size = 0.
     */
    subtree_size: number;
    /**
     * True when at least one comment by another user is newer than the viewer's comment-read watermark (AURA-999 / AURA-1082). Same rule as TaskListItem.has_unread_comments.
     *
     */
    has_unread_comments: boolean;
    /**
     * Strict position within rank_context; null = unprioritized (AURA-930 / AURA-1135).
     */
    rank?: number;
    /**
     * Priority-order context key (AURA-930 / AURA-1135).
     */
    rank_context: string;
    /**
     * ASAP class flag (AURA-930).
     */
    asap: boolean;
    /**
     * Optional ranking justification (AURA-930).
     */
    rank_reason?: string;
};

/**
 * Parent→child hierarchy edge; both endpoints are always board nodes.
 */
export type TaskBoardHierarchyEdge = {
    /**
     * Stable edge id ("hier:<parent-uuid>:<child-uuid>")
     */
    id: string;
    /**
     * Parent task UUID
     */
    source: string;
    /**
     * Child task UUID
     */
    target: string;
};

/**
 * Typed TaskRelation edge; both endpoints are always board nodes.
 */
export type TaskBoardRelationEdge = {
    /**
     * Stable edge id ("rel:<relation-uuid>")
     */
    id: string;
    /**
     * Source task UUID (TaskRelation.fromTask)
     */
    source: string;
    /**
     * Target task UUID (TaskRelation.toTask)
     */
    target: string;
    type: TaskRelationType;
};

/**
 * Stored canvas position of one card, for the calling user only.
 */
export type TaskBoardPosition = {
    /**
     * Task UUID the position belongs to
     */
    task_id: string;
    /**
     * Canvas x coordinate of the card's top-left corner
     */
    x: number;
    /**
     * Canvas y coordinate of the card's top-left corner
     */
    y: number;
};

/**
 * Stored pan/zoom of the board canvas, for the calling user only.
 */
export type TaskBoardViewport = {
    x: number;
    y: number;
    zoom: number;
};

/**
 * Unpaginated board payload — nodes, both edge kinds and the caller's stored layout in one response.
 */
export type TaskBoard = {
    nodes: Array<TaskBoardNode>;
    hierarchy_edges: Array<TaskBoardHierarchyEdge>;
    relation_edges: Array<TaskBoardRelationEdge>;
    /**
     * The caller's stored card positions, restricted to tasks present in `nodes`. Stored positions of tasks that left the board are ignored here and kept in the database. Empty when nothing is stored yet.
     */
    positions: Array<TaskBoardPosition>;
    /**
     * Stored viewport; absent when the caller has none yet.
     */
    viewport?: TaskBoardViewport;
    /**
     * The caller's stored expand/collapse state. Absent when the caller has none yet — the frontend treats absence as "everything collapsed" (the default start).
     */
    collapsed?: TaskBoardCollapsedState;
};

/**
 * Per-user expand/collapse state for the board diagram. Stored as JSONB in UserTaskBoardState.collapsed. The default (absent / empty) means everything is collapsed — only top-level objects and aggregate boxes are visible.
 */
export type TaskBoardCollapsedState = {
    /**
     * Task UUIDs whose direct children are currently visible.
     */
    expanded_task_ids?: Array<string>;
    /**
     * Which aggregate boxes are currently expanded.
     */
    expanded_boxes?: Array<'orphan_epics' | 'orphan_stories' | 'unleveled'>;
};

/**
 * upsert = overwrite existing positions (single move, Reset); create_only = only create missing ones (first snapshot, race-safe).
 */
export type TaskBoardLayoutWriteMode = 'upsert' | 'create_only' | 'clear';

/**
 * Bulk layout write for the calling user.
 */
export type TaskBoardLayoutWrite = {
    /**
     * Positions to store. May be empty when only the viewport changes.
     */
    positions: Array<TaskBoardPosition>;
    /**
     * Viewport to store; omit to leave the stored viewport untouched.
     */
    viewport?: TaskBoardViewport;
    /**
     * Expand/collapse state to store. Omit to leave the stored state untouched. In create_only mode, an existing state is never overwritten.
     */
    collapsed?: TaskBoardCollapsedState;
    /**
     * Defaults to `upsert` when omitted.
     */
    mode?: TaskBoardLayoutWriteMode;
};

/**
 * What the write actually did. `skipped` counts positions left untouched — because they already existed and the mode was create_only, or because the task is not on the caller's board.
 */
export type TaskBoardLayoutWriteResult = {
    created: number;
    updated: number;
    skipped: number;
};

