/**
 * Fixed role a task member can hold (ANW-7230). A member may hold multiple roles.
 */
export type TaskRole = 'OWNER' | 'CONTRIBUTOR' | 'STAKEHOLDER';

/**
 * Task-internal capability (T18 · S04, ANW-7608), mirrored 1:1 from the server-side matrix in src/server/lib/access/taskCapabilities.ts.
 */
export type TaskCapability = 'TASK_COMMENT' | 'TASK_CREATE_REVIEW' | 'TASK_VIEW_ANCESTOR_TITLE' | 'TASK_EDIT_CONTENT' | 'TASK_MANAGE_LINKS' | 'TASK_MANAGE_MEMBERS' | 'TASK_MANAGE_LIFECYCLE';

/**
 * The current viewer's effective access on this task (ANW-7750). Powers UI gating (members/lifecycle/content edit) without deriving rights from the members list alone — Admin/Leadership override elevates capabilities without inventing a synthetic OWNER membership.
 *
 */
export type ViewerAccess = {
    /**
     * Effective permission lattice level from resolveTaskAccess.
     */
    permission: 'NONE' | 'READ' | 'EDIT' | 'MANAGE';
    /**
     * Effective task capabilities after applying the system-role override (if any).
     */
    capabilities: Array<TaskCapability>;
    /**
     * True when ADMIN/LEADERSHIP granted MANAGE via the systemRole source.
     */
    via_system_override: boolean;
    /**
     * True only when the viewer holds TaskRole.OWNER on a member row — never set by the system override alone.
     */
    is_owner: boolean;
};

/**
 * One access holder on a task — a direct member, a TaskAccessGrant, or a member inherited from an ancestor task (T18 · S07, ANW-7613) — with the resulting effective access level and the concrete capabilities it grants.
 *
 */
export type AccessOverviewEntry = {
    /**
     * Kind of principal this entry represents. COMPANY has no individual user (whole-company grant); GROUP is a seam, not yet populated.
     */
    principal_type: 'USER' | 'GROUP' | 'COMPANY';
    /**
     * The user this entry represents; null for COMPANY (and for GROUP, not yet implemented).
     */
    principal?: {
        /**
         * User UUID
         */
        id: string;
        display_name?: string;
        email?: string;
    };
    /**
     * TaskRole(s) held by this principal — on this task, or on the source ancestor task for inherited entries.
     */
    roles: Array<TaskRole>;
    /**
     * Resulting effective access level on this task, mirroring resolveTaskAccess. Inherited membership derives its level from the roles held on the source ancestor task (N1, ANW-7886). Inherited grant origin entries (S5, ANW-7888) are always READ, mirroring the grant cascade's fixed cap — independent of the roles on the ancestor's TaskAccessGrant.
     *
     */
    level: 'READ' | 'EDIT' | 'MANAGE';
    /**
     * Concrete capabilities this level grants, mirroring hasTaskCapability's matrix.
     */
    capabilities: Array<TaskCapability>;
    /**
     * Whether this entry derives from a TaskMember row or from a TaskAccessGrant. Orthogonal to the group it sits in: the `inherited` array holds both kinds.
     *
     */
    origin: 'member' | 'grant';
    /**
     * The ancestor task this entry's membership is inherited from; present only for inherited entries.
     */
    source_task?: {
        /**
         * Source task UUID
         */
        id: string;
        /**
         * Source task title
         */
        title: string;
    };
};

/**
 * Read-only aggregation of everyone with access to a task — direct members, TaskAccessGrants (COMPANY today; GROUP is a seam), and members inherited from ancestor tasks — powering the access-overview modal (T18 · S07, ANW-7613). Purely informational; contains no mutation affordances.
 *
 */
export type AccessOverview = {
    /**
     * Direct TaskMembers.
     */
    direct: Array<AccessOverviewEntry>;
    /**
     * TaskAccessGrant rows (COMPANY today; GROUP is a seam, not yet populated).
     */
    grants: Array<AccessOverviewEntry>;
    /**
     * Members inherited from ancestor tasks (S5, ANW-7610); each entry always carries source_task.
     */
    inherited: Array<AccessOverviewEntry>;
};

/**
 * One source of broad (non-individual) access to a task or artifact — a whole-company or group grant (direct or inherited), or an open owner-/crew-search that currently lets any user read (ANW-7907, S1). Powers the warning box in ShareModal, computed by a dedicated server helper so the UI never re-derives access policy. USER-type grants are intentionally excluded — individual access belongs in the person list, not here.
 *
 */
export type BroadAccessEntry = {
    /**
     * Source of the broad access.
     */
    kind: 'COMPANY_GRANT' | 'GROUP_GRANT' | 'OWNER_SEARCH' | 'CREW_SEARCH';
    /**
     * True when this entry comes from an ancestor task's grant rather than the object's own.
     */
    inherited: boolean;
    /**
     * Resulting effective access level, generated via permissionLabel. Direct grants derive it from the grant's roles; inherited grants and open searches are always READ (the fixed cascade cap).
     *
     */
    level: 'READ' | 'EDIT' | 'MANAGE';
    /**
     * Group display name for GROUP_GRANT once group resolution exists (ANW-7611 seam); null for every other kind today.
     */
    principal_name: string;
    /**
     * The ancestor task this entry's grant is inherited from; null for direct grants and for search-flag entries.
     */
    source_task: {
        /**
         * Source task UUID
         */
        id: string;
        /**
         * Source task title
         */
        title: string;
    };
};

/**
 * Participation status of a task member (T18 · S33, ANW-7583). ACTIVE = currently driving the task forward; WAITING = involved but temporarily blocked; OBSERVING = only watching, no action expected. Derived from the role by default (STAKEHOLDER → OBSERVING, otherwise ACTIVE), and settable self-declared or via an owner directive.
 *
 */
export type ParticipationStatus = 'ACTIVE' | 'WAITING' | 'OBSERVING';

/**
 * A task member together with their assigned roles and participation
 */
export type TaskMemberWithRoles = {
    user: UserPickerItem;
    /**
     * Roles assigned to this member on the task
     */
    roles: Array<TaskRole>;
    /**
     * Free-text sentence describing this member's concrete contribution on this task; not mandatory.
     */
    participation_note?: string;
    participation_status: ParticipationStatus;
    /**
     * T18 · S27 (ANW-7772): the member's committed capacity on this task as a percentage of a full position (10% steps, 0..100). Null = no commitment set. Only core-team members (OWNER/CONTRIBUTOR) set it.
     */
    capacity_percent?: number;
};

/**
 * T18 · S27 (ANW-7772): set/change/remove a core-team member's capacity commitment on a task. Null clears the commitment.
 */
export type TaskMemberCapacityUpdate = {
    /**
     * Commitment as a percentage of a full position, in 10% steps (0..100). Null removes the commitment.
     */
    capacity_percent: number;
};

/**
 * Sort field for the leadership capacity overview.
 */
export type CapacitySortField = 'name' | 'utilization';

/**
 * One active task a person is a direct member of, with their roles and (for core-team roles) their committed capacity.
 */
export type CapacityTaskCommitment = {
    task_id: string;
    /**
     * Human-readable, immutable task identifier (e.g. "AURA-42") — used for browser links; task_id stays the API identifier (ANW-7848).
     */
    human_key: string;
    task_title: string;
    task_status: TaskStatus;
    roles: Array<TaskRole>;
    /**
     * The person's committed capacity on this task (null when unset or not a core-team role).
     */
    capacity_percent: number;
    /**
     * Hierarchy level of the task (null when unleveled).
     */
    task_level: TaskLevel;
    /**
     * Ancestors from root to direct parent (empty when the task is a root). Used by the leadership matrix to build the hierarchy tree.
     */
    hierarchy_path: Array<TaskHierarchyRef>;
    /**
     * The governing deadline of this task, or null when none applies. AURA-1722 / S7: comes straight from `governingDeadline` (no second selection logic), so the payload value and the board display agree. Carries NO ampel and NO overdue flag — the verdict lives in the consuming skill.
     */
    governing_deadline?: string;
};

/**
 * T18 · S27 (ANW-7772): one person's company-wide capacity summary plus their active-task participation (direct roles only). AURA-1722 / S5: an optional `group` assignment is carried only by `scope: group` rows; null for the other scopes. AURA-1722 / S6: `capacity_updated_at` is the most recent time the person themselves touched their capacity on any of their memberships (unfiltered aggregation, D9); null means "never recorded", not "stale" (D16).
 */
export type CapacityLeadershipRow = {
    user: UserPickerItem;
    /**
     * The person's base capacity (percentage of a full position).
     */
    base_percent: number;
    /**
     * Sum of the person's capacity commitments across active tasks.
     */
    committed_percent: number;
    /**
     * base_percent minus committed_percent (may be negative when over-committed).
     */
    free_percent: number;
    /**
     * committed_percent / base_percent as a percentage (0 when base is 0).
     */
    utilization_percent: number;
    /**
     * True when committed_percent exceeds base_percent (soft-limit warning).
     */
    over: boolean;
    tasks: Array<CapacityTaskCommitment>;
    /**
     * Group assignment carried only by `scope: group` rows (AURA-1722 / S5); null for me/person/company. A person in two of the caller's groups produces two rows, each with its own group.
     */
    group?: {
        uuid?: string;
        name?: string;
    };
    /**
     * When the person themselves last touched their capacity on any of their memberships (AURA-1722 / S6 / D9). Comes from an UNFILTERED aggregation over TaskMember (max per user), so a capacity set today on a task completed the same day still counts. Moves only on a self-attributable change (D17); a foreign-set or system-cleared capacity leaves it untouched. null means "never recorded" (legacy row, or no self-set yet), NOT "stale" (D16 — no backfill). Delivered as null, never mapped away.
     */
    capacity_updated_at?: string;
};

/**
 * Paginated, person-centric leadership capacity/participation overview.
 */
export type CapacityLeadershipList = {
    items: Array<CapacityLeadershipRow>;
    pagination: Pagination;
};

/**
 * AURA-1722: one row of a scoped capacity read. Same fields as CapacityLeadershipRow, except that `tasks` is optional: scope=me/person carry the person's active-task list, scope=group/company carry the aggregates only — a measured scope=company answer with every task in every row reached ~122k tokens and left no room for a reply. When absent the field is omitted, never sent as an empty array: for a group row an empty list means "this member holds no active task" (D11), so an empty array would turn a missing field into a false fact. Ask again with scope=person to get one member's tasks.
 */
export type CapacityReadRow = {
    user: UserPickerItem;
    /**
     * The person's base capacity (percentage of a full position).
     */
    base_percent: number;
    /**
     * Sum of the person's capacity commitments across active tasks. Exact for every scope — summed from the full commitments before the task list is dropped.
     */
    committed_percent: number;
    /**
     * base_percent minus committed_percent (may be negative when over-committed).
     */
    free_percent: number;
    /**
     * committed_percent / base_percent as a percentage (0 when base is 0).
     */
    utilization_percent: number;
    /**
     * True when committed_percent exceeds base_percent (soft-limit warning).
     */
    over: boolean;
    /**
     * The person's active tasks and commitments. Present for scope=me/person, omitted for scope=group/company.
     */
    tasks?: Array<CapacityTaskCommitment>;
    /**
     * Group assignment carried only by `scope: group` rows (AURA-1722 / S5); null for me/person/company. A person in two of the caller's groups produces two rows, each with its own group.
     */
    group?: {
        uuid?: string;
        name?: string;
    };
    /**
     * When the person themselves last touched their capacity on any of their memberships (AURA-1722 / S6 / D9). Unfiltered aggregation over TaskMember (max per user). Moves only on a self-attributable change (D17). null means "never recorded" (D16 — no backfill), NOT "stale". Delivered as null, never mapped away.
     */
    capacity_updated_at?: string;
};

/**
 * AURA-1722: scoped capacity read. One unified list shape for all scopes — scope=me/person is a one-row list, scope=group is the roster (each row carries its group), scope=company is the paginated firm-wide overview. The row shape is CapacityReadRow, whose `tasks` is optional per scope; CapacityLeadershipRow keeps `tasks` required for the leadership board, which needs it.
 */
export type CapacityReadResponse = {
    items: Array<CapacityReadRow>;
    /**
     * Total number of rows across all pages (1 for scope=me).
     */
    total: number;
    pagination: Pagination;
};

/**
 * T18 · S27 (ANW-7772): the logged-in user's own capacity — KPI values plus their active tasks and commitments. AURA-1722 / S6: `capacity_updated_at` is the most recent time the person themselves touched their capacity on any of their memberships (unfiltered aggregation, D9); null means "never recorded", not "stale" (D16).
 */
export type CapacityPersonal = {
    base_percent: number;
    /**
     * Optional company override for the base-capacity explanation shown to employees; null → localized default.
     */
    base_capacity_note?: string;
    committed_percent: number;
    free_percent: number;
    utilization_percent: number;
    over: boolean;
    tasks: Array<CapacityTaskCommitment>;
    /**
     * When the person themselves last touched their capacity on any of their memberships (AURA-1722 / S6 / D9). Unfiltered aggregation over TaskMember (max per user). Moves only on a self-attributable change (D17). null means "never recorded" (D16 — no backfill), NOT "stale". Delivered as null, never mapped away.
     */
    capacity_updated_at?: string;
};

/**
 * T18 · S27 (ANW-7772): company-wide base capacity setting (singleton).
 */
export type CapacitySettings = {
    /**
     * Firm-wide base capacity in 10% steps (10..100). Persons without a personal override inherit this.
     */
    base_capacity_percent: number;
    /**
     * Optional admin override for the base-capacity explanation; null → localized default.
     */
    base_capacity_note: string;
    updated_at: string;
    updated_by: UserPickerItem;
};

/**
 * A member inherited from an ancestor task (S5, ANW-7610). Read-only at the child level — not removable or role-editable.
 */
export type InheritedMember = {
    user: {
        /**
         * User UUID
         */
        id: string;
        display_name?: string;
        email?: string;
    };
    /**
     * Roles the user holds on the source ancestor task
     */
    roles: Array<string>;
    /**
     * The ancestor task from which this membership is inherited
     */
    source_task: {
        /**
         * Source task UUID
         */
        id: string;
        /**
         * Human-readable, immutable identifier of the source task, used to build readable task links (ANW-7857).
         */
        human_key: string;
        /**
         * Source task title
         */
        title: string;
    };
};

