/**
 * One row of the per-phase "Phasen-Rahmen" roadmap (T18 · S28, ANW-7516; per-phase key ANW-7764): the deadline and free-text goal for one work phase.
 *
 */
export type TaskPhaseGoal = {
    /**
     * The work phase this goal is for (refinement/alignment/development/ review/deployment). A free string, validated against the phases present in the task's status series in the API layer.
     *
     */
    phase: string;
    /**
     * Day-only deadline (no time component).
     */
    deadline: string;
    /**
     * Free-text phase goal ("Auftrag der Runde"), may be empty.
     */
    goal_description: string;
    /**
     * True when the deadline is set, lies before today, and the owning task is still due-relevant (not DONE/DISCARDED, not archived). Traffic-light thresholds (YELLOW/RED windows) remain separate (S14 / classifyDeadlineAmpel).
     *
     */
    is_overdue: boolean;
    created_at: string;
    updated_at: string;
};

/**
 * Payload for creating/updating the phase-goal row for one target status (all fields optional).
 */
export type TaskPhaseGoalUpsert = {
    /**
     * Day-only deadline, or null to clear it.
     */
    deadline?: string;
    /**
     * Free-text phase goal.
     */
    goal_description?: string;
};

/**
 * One dirty row from the combined status-history/phase-goal table. A row with `deadline: null` and an empty `goal_description` deletes the phase goal for that phase instead of upserting it.
 *
 */
export type TaskPhaseGoalBatchUpsertItem = {
    /**
     * The work phase this goal is for (must be one of the phases present in the task's status series and not yet passed).
     *
     */
    phase: string;
    /**
     * Day-only deadline, or null to clear it.
     */
    deadline: string;
    /**
     * Free-text phase goal, may be empty.
     */
    goal_description: string;
};

/**
 * Batch payload for saving every dirty phase-goal row in one atomic call.
 */
export type TaskPhaseGoalBatchUpsert = {
    goals: Array<TaskPhaseGoalBatchUpsertItem>;
};

