/**
 * Sortable fields for LLM turn list
 */
export type LlmTurnSortField = 'created_at' | 'model' | 'run_name' | 'duration_ms';

/**
 * A single LLM provider call (one iteration of the agentic loop)
 */
export type LlmTurn = {
    /**
     * Internal DB ID
     */
    id: number;
    /**
     * Public UUID
     */
    uuid: string;
    /**
     * Logical run name (e.g. aura-chat-stream)
     */
    run_name: string;
    /**
     * Model identifier
     */
    model: string;
    /**
     * Iteration index within the agentic loop (0-based)
     */
    iteration_index: number;
    /**
     * Whether the full payload (system prompt, messages, raw response) is available via GET /llm-turns/{uuid}/payload. False for turns predating payload-to-S3 storage, or if the S3 write failed.
     */
    has_payload: boolean;
    input_tokens?: number;
    output_tokens?: number;
    cached_input_tokens?: number;
    reasoning_tokens?: number;
    /**
     * Estimated cost in USD
     */
    cost_usd?: number;
    /**
     * Wall-clock duration of the model call in milliseconds
     */
    duration_ms?: number;
    success: boolean;
    error_message?: string;
    /**
     * UUID of the associated ChatMessage
     */
    chat_message_id?: string;
    /**
     * UUID of the associated Chat
     */
    chat_id?: string;
    created_at: string;
    /**
     * Raw provider stop reason (e.g. tool_use, end_turn). Null on turns predating this field.
     */
    stop_reason?: string;
    /**
     * Tools requested in this turn. Null when unknown (old turns); empty when the turn requested none.
     */
    tools?: Array<LlmTurnTool>;
};

/**
 * A tool the model requested in this LLM turn
 */
export type LlmTurnTool = {
    name: string;
    provider_call_id?: string;
    kind: 'tool' | 'frontend_tool';
    /**
     * Arguments as logged when the model requested the tool
     */
    args?: unknown;
    /**
     * ChatToolCall result when a matching row exists. Always null for frontend_tool.
     */
    result?: unknown;
    /**
     * ChatToolCall status when a matching row exists
     */
    status?: string;
};

/**
 * Paginated list of LLM turns
 */
export type LlmTurnList = {
    /**
     * LLM turn items for the current page
     */
    items: Array<LlmTurn>;
    pagination: Pagination;
};

/**
 * Full payload content of a single LLM turn, loaded from S3 on demand
 */
export type LlmTurnPayload = {
    /**
     * Resolved system prompt sent to the model
     */
    system_prompt?: string;
    /**
     * Messages sent to the model (serialised LangChain format)
     */
    input_messages?: unknown;
    /**
     * Plain text content of the model response
     */
    response_text?: string;
    /**
     * Raw model response chunks (JSON)
     */
    raw_response?: unknown;
    /**
     * Model parameters (e.g. reasoningEffort)
     */
    parameters?: unknown;
};

